pe-archive-album .archive-header{margin-bottom:1.5rem}\nbody.post-type-archive-album .archive-filter{background:#1f4c8f;color:#fff;padding:1rem;border-radius:6px;margin-bottom:1.5rem}\nbody.post-type-archive-album .archive-filter form{display:flex;gap:.75rem;align-items:center;flex-wrap:wrap}\nbody.post-type-archive-album .album-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1.25rem}\nbody.post-type-archive-album .album-card{background:#f8f8f8;padding:1rem;border-radius:8px;box-shadow:0 2px 6px rgba(0,0,0,.08);position:relative}\nbody.post-type-archive-album .album-date{position:absolute;top:-12px;left:-12px;background:#4a6fb4;color:#fff;border-radius:8px;padding:.4rem .6rem;text-align:center}\nbody.post-type-archive-album .album-date .album-day{display:block;font-weight:700}\nbody.post-type-archive-album .album-date .album-month{display:block;font-size:.85rem;opacity:.95}\nbody.post-type-archive-album .album-thumbnail img{width:100%;height:auto;border-radius:6px;margin-bottom:.5rem}\nbody.post-type-archive-album .album-title{margin:.5rem 0}\nbody.post-type-archive-album .archive-pagination{text-align:center;margin-top:1.5rem}\nbody.post-type-archive-album .archive-pagination ul{list-style:none;padding:0;margin:0;display:inline-flex;gap:.5rem}\nbody.post-type-archive-album .archive-pagination a,\nbody.post-type-archive-album .archive-pagination span{display:inline-block;padding:.5rem .9rem;border-radius:4px;background:#1f4c8f;color:#fff;text-decoration:none}\n.album-card .album-date{display:inline-block;background:#1f4c8f !important;color:#fff !important;padding:2px 8px;font-size:.9rem;font-weight:700;border-radius:6px;margin:0 0 6px 0;width:auto}.album-card .album-date .wp-block-post-date{color:#fff !important;margin:0}\n@media (max-width: 900px) {\n  .hide-on-overflow {\n    display: none !important;\n  }\n}\n\n.no-margin {\n  margin: 0 !important;\n}\n\n.rss-feed {\n  font-size: 14px;\n}\n\n/* grid niceness (optional if you\'re using columns) */\n.people-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 1rem; }\n\n/* cover cards */\n.person-card { transition: transform .25s ease; }\n.person-card:hover { transform: translateY(-2px); }\n\n.person-card .wp-block-cover__background { transition: opacity .25s ease, background-color .25s ease; opacity: .0; }\n.person-card:hover .wp-block-cover__background { opacity: .5; }  /* remove dim on hover */\n\n/* text reveal on hover */\n.person-card .wp-block-cover__inner-container { transition: opacity .25s ease, transform .25s ease; opacity: 0; transform: translateY(8px); }\n.person-card:hover .wp-block-cover__inner-container { opacity: 1; transform: translateY(0); }\n\n/* keyboard accessibility: show text on focus */\n.person-card:focus-within .wp-block-cover__inner-container { opacity: 1; transform: translateY(0); }\n\n/* reduce motion preference */\n@media (prefers-reduced-motion: reduce) {\n  .person-card, .person-card .wp-block-cover__background, .person-card .wp-block-cover__inner-container { transition: none; }\n}\n\n:root :where(.wp-block-columns-is-layout-flow) > :first-child{margin-block-start: 0;}:root :where(.wp-block-columns-is-layout-flow) > :last-child{margin-block-end: 0;}:root :where(.wp-block-columns-is-layout-flow) > *{margin-block-start: var(--wp--preset--spacing--50);margin-block-end: 0;}:root :where(.wp-block-columns-is-layout-constrained) > :first-child{margin-block-start: 0;}:root :where(.wp-block-columns-is-layout-constrained) > :last-child{margin-block-end: 0;}:root :where(.wp-block-columns-is-layout-constrained) > *{margin-block-start: var(--wp--preset--spacing--50);margin-block-end: 0;}:root :where(.wp-block-columns-is-layout-flex){gap: var(--wp--preset--spacing--50);}:root :where(.wp-block-columns-is-layout-grid){gap: var(--wp--preset--spacing--50);}\n:root :where(.wp-block-buttons-is-layout-flow) > :first-child{margin-block-start: 0;}:root :where(.wp-block-buttons-is-layout-flow) > :last