le-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group alignwide is-style-default has-base-color has-text-color has-link-color\" style=\"padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:site-logo {\"width\":156} /-->\n\n<!-- wp:group {\"tagName\":\"header\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<header class=\"wp-block-group\"><!-- wp:navigation {\"ref\":5} /--></header>\n<!-- /wp:group --></div>\n<!-- /wp:group --></header>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"backgroundColor\":\"accent-1\",\"textColor\":\"base\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull is-style-default has-base-color has-accent-1-background-color has-text-color has-background has-link-color\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--50);padding-left:0\"><!-- wp:group {\"className\":\"is-style-section-4\",\"style\":{\"position\":{\"type\":\"\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group is-style-section-4\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:paragraph -->\n<p>Get Involved</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"base\",\"iconColorValue\":\"#FFFFFF\",\"className\":\"is-style-logos-only\"} -->\n<ul class=\"wp-block-social-links has-icon-color is-style-logos-only\"><!-- wp:social-link {\"url\":\"https://www.facebook.com/shasa.energy/\",\"service\":\"facebook\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.youtube.com/@stevecolman837\",\"service\":\"youtube\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"75%\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:75%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--50);padding-bottom:0;padding-left:var(--wp--preset--spacing--50)\"><!-- wp:site-logo {\"width\":451,\"style\":{\"color\":{\"duotone\":\"unset\"},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} /-->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\">The Southcoast Health and Sustainability Alliance (SHASA) is an alliance of Eurobodalla community members. Formed in 2014 SHASA’s key focus is to highlight and support action to mitigate climate change for our region.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\">SHASA recognises Aboriginal people of the Yuin Nation as the original inhabitants and cu